mapper.select:
SELECT COUNT(*)
FROM (
    SELECT S_USER_ID AS checkId
    FROM STORE_USER
    WHERE S_USER_ID = #{sUserId}
      AND S_USER_ID != #{originUserId}

    UNION ALL

    SELECT USER_ID AS checkId
    FROM USERS
    WHERE USER_ID = #{sUserId}

    UNION ALL

    SELECT ADMIN_ID AS checkId
    FROM TBL_ADMIN
    WHERE ADMIN_ID = #{sUserId}
) A

mapper.update:
UPDATE STORE_USER
SET
	S_USER_ID = #{sUserId},
	S_USER_PWD = #{sUserPwd}
WHERE S_USER_ID = #{originUserId}

mapper.select:
SELECT R.REVIEW_NO AS reviewNo, U.USER_NAME AS userName, U.NICKNAME AS nickname, SM.MENU_NO AS menuNo, SM.MENU_NAME AS menuName, R.RATING AS rating, R.R_CONTENTS AS rContents, R.CDATE AS reviewDate, RF.FILE_PATH AS filePath, RF.FILE_NAME AS fileName, RR.REP_STATUS AS repStatus, R.RSV_NO AS rsvNo FROM REVIEW R LEFT JOIN USERS U ON R.USER_ID = U.USER_ID LEFT JOIN RESERVATION RE ON R.RSV_NO = RE.RSV_NO LEFT JOIN STORE_MENU SM ON RE.MENU_NO = SM.MENU_NO LEFT JOIN STORE S ON R.STORE_NO = S.STORE_NO LEFT JOIN STORE_USER SU ON S.S_USER_ID = SU.S_USER_ID LEFT JOIN REVIEW_REPORT RR ON R.REVIEW_NO = RR.REVIEW_NO AND RR.REPORTER_ID = #{sUserId} LEFT JOIN REVIEW_FILE RF ON RF.REVIEW_NO = R.REVIEW_NO AND RF.FILE_NO = ( SELECT MIN(RF2.FILE_NO) FROM REVIEW_FILE RF2 WHERE RF2.REVIEW_NO = R.REVIEW_NO ) WHERE S.S_USER_ID = #{sUserId} AND S.S_STATUS IN ('GEN', 'AFF') AND SU.U_STATUS = 'APR'
AND SM.MENU_NO = #{menuNo}
ORDER BY R.CDATE DESC
